package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PortVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property port of smtp outbound config ")
  void test_port_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> PortVO.tryFrom(null));
    Assertions.assertEquals(1, PortVO.from(1).getPort());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PortVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", PortVO.from(1).toString());
  }
}
